.bookcraft {
  --bc-gap: clamp(10px, 1.8vh, 16px);
  --bc-pad-x: clamp(16px, 4.8vw, 28px);
  --bc-pad-y: clamp(12px, 2.4vh, 20px);
  --bc-title-size: clamp(24px, calc(var(--reader-font-size, 18px) * 1.3), 38px);
  --bc-meta-size: clamp(11px, calc(var(--reader-font-size, 18px) * .62), 14px);
  --bc-ornament: var(--reader-accent, currentColor);
  --bc-art-height: clamp(72px, 13.8vh, 104px);
  position: relative;
  box-sizing: border-box;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-rows: auto minmax(0, 1fr) auto;
  gap: var(--bc-gap);
  width: 100%; height: 100%; min-width: 0; min-height: 0;
  padding: var(--bc-pad-y) var(--bc-pad-x);
  color: var(--reader-text-color, inherit);
  background: var(--reader-page-background, transparent);
}
.bookcraft .bc-opening, .bookcraft .bc-running, .bookcraft .bc-footer { position: relative; min-width: 0; }
.bookcraft .bc-body { min-width: 0; min-height: 0; }
.bookcraft .reader-chapter-title { display: none; }
.bookcraft .bc-kicker {
  display: flex; align-items: center; gap: 12px;
  min-width: 0; margin: 0 0 8px;
  font-size: var(--bc-meta-size); line-height: 1.45; text-align: center;
}
.bookcraft .bc-book { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; letter-spacing: .065em; }
.bookcraft .bc-kicker-rule { flex: 0 0 28px; border-top: 1px solid currentColor; opacity: .28; }
.bookcraft .bc-frontispiece {
  position: relative; height: var(--bc-art-height); margin: 0 auto 9px;
  color: var(--bc-ornament); max-width: 100%;
}
.bookcraft .bc-frontispiece > svg { display: block; width: 100%; height: 100%; overflow: visible; }
.bookcraft .bc-title {
  display: block; margin: 0; padding: 0;
  font-size: var(--bc-title-size); line-height: 1.42; font-weight: 600;
  font-style: normal; font-family: inherit; letter-spacing: .025em;
  text-align: center; text-indent: 0; overflow-wrap: anywhere;
  word-break: normal; hyphens: none;
}
.bookcraft .bc-terminal {
  width: min(176px, 62%); height: 20px; margin: 10px auto 0;
  color: var(--bc-ornament);
}
.bookcraft .bc-terminal > svg { display: block; width: 100%; height: 100%; }
.bookcraft .bc-running {
  display: flex; align-items: center; gap: 10px;
  padding-bottom: 7px; border-bottom: 1px solid currentColor;
  font-size: var(--bc-meta-size); line-height: 1.5;
}
.bookcraft .bc-running-title {
  flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  text-align: center; letter-spacing: .025em;
}
.bookcraft .bc-running-mark { display: block; flex: none; width: 25px; height: 23px; color: var(--bc-ornament); }
.bookcraft .bc-running-mark > svg { display: block; width: 100%; height: 100%; }
.bookcraft .bc-running-index { flex: none; min-width: 1.2em; text-align: end; font-variant-numeric: tabular-nums; }
.bookcraft .bc-footer-art { position: relative; height: 28px; margin-bottom: 5px; color: var(--bc-ornament); }
.bookcraft .bc-footer-art > svg { display: block; width: 100%; height: 100%; }
.bookcraft .bc-meta {
  display: grid; grid-template-columns: minmax(0, 1fr) auto auto minmax(0, 1fr);
  align-items: baseline; gap: 10px; min-width: 0;
  font-size: var(--bc-meta-size); line-height: 1.5; font-style: normal;
  font-weight: 400; letter-spacing: .015em; font-variant-numeric: tabular-nums;
}
.bookcraft .bc-meta > * { min-width: 0; white-space: nowrap; text-indent: 0; }
.bookcraft .bc-meta > :first-child { text-align: start; }
.bookcraft .bc-meta > :last-child { text-align: end; }
.bookcraft .bc-page-number { font-weight: 600; letter-spacing: .025em; }
.bookcraft .bc-time, .bookcraft .bc-progress, .bookcraft .bc-battery { opacity: .82; }
.bookcraft [data-reader-decoration] { pointer-events: none; user-select: none; }
.bookcraft [data-reader-decoration] svg { pointer-events: none; }
.bookcraft svg .bc-light { opacity: .32; }
.bookcraft svg .bc-faint { opacity: .16; }
.bookcraft svg .bc-soft { opacity: .62; }
.bookcraft .ornate-entry { opacity: 1; transform: none; }
.reader-template-page .bookcraft [data-reader-ambient] { animation-play-state: paused; }
.reader-template-page[data-reader-motion="running"] .bookcraft [data-reader-ambient] { animation-play-state: running; }
.reader-template-page[data-reader-motion="settled"] .bookcraft [data-reader-ambient] { animation: none; }
.reader-template-page[data-reader-motion="running"][data-reader-entry="playing"] .bookcraft .ornate-entry {
  animation: bookcraft-title-entry 760ms cubic-bezier(.2,.72,.22,1) both;
}
@keyframes bookcraft-title-entry {
  from { opacity: .76; transform: translateY(6px); }
  to { opacity: 1; transform: none; }
}
.bookcraft[data-bookcraft-density="compact"] { --bc-art-height: 42px; --bc-gap: 8px; --bc-pad-y: 10px; }
.bookcraft[data-bookcraft-density="compact"] .bc-kicker { margin-bottom: 4px; }
.bookcraft[data-bookcraft-density="compact"] .bc-frontispiece { margin-bottom: 6px; }
.bookcraft[data-bookcraft-density="compact"] .bc-terminal { height: 14px; margin-top: 6px; }
.bookcraft[data-bookcraft-density="compact"] .bc-footer-art { height: 22px; margin-bottom: 3px; }
.bookcraft[data-bookcraft-density="minimal"] { --bc-art-height: 20px; --bc-gap: 6px; --bc-pad-y: 7px; }
.bookcraft[data-bookcraft-density="minimal"] .bc-kicker { margin-bottom: 3px; }
.bookcraft[data-bookcraft-density="minimal"] .bc-frontispiece { margin-bottom: 3px; }
.bookcraft[data-bookcraft-density="minimal"] .bc-terminal { height: 10px; margin-top: 4px; }
.bookcraft[data-bookcraft-density="minimal"] .bc-footer-art { height: 17px; margin-bottom: 2px; }
.bookcraft[data-bookcraft-density="minimal"] .bc-running { padding-bottom: 4px; }
.bookcraft[data-bookcraft-density="minimal"] .bc-running-mark { width: 19px; height: 18px; }
@media (max-width: 340px) {
  .bookcraft { --bc-pad-x: 16px; }
  .bookcraft .bc-meta { gap: 7px; }
}
@media (max-height: 480px) {
  .bookcraft { --bc-art-height: 38px; --bc-gap: 7px; --bc-pad-y: 8px; --bc-meta-size: 11px; }
  .bookcraft .bc-kicker { margin-bottom: 3px; }
  .bookcraft .bc-frontispiece { margin-bottom: 4px; }
  .bookcraft .bc-terminal { height: 12px; margin-top: 4px; }
  .bookcraft .bc-footer-art { height: 20px; margin-bottom: 2px; }
  .bookcraft .bc-running { padding-bottom: 4px; }
}
@media (prefers-reduced-motion: reduce) {
  .reader-template-page .bookcraft [data-reader-ambient],
  .reader-template-page[data-reader-motion="running"][data-reader-entry="playing"] .bookcraft .ornate-entry { animation: none; }
}
.bookcraft--night .bc-frontispiece { width: 100%; }
.bookcraft--night .bc-title { letter-spacing: .065em; }
.bookcraft--night .bc-running { border-bottom-color: transparent; }
.bookcraft--night .bc-running::after {
  position: absolute; content: ""; bottom: 0; left: 0; right: 0;
  height: 1px; background: currentColor; opacity: .24;
}
.bookcraft--night .bc-night-glimmer {
  animation: bc-night-glimmer 5.4s ease-in-out infinite alternate;
  animation-delay: var(--bc-night-delay, 0s);
}
@keyframes bc-night-glimmer { from { opacity: .4; } to { opacity: .96; } }
/* Bookcraft: one real initial glyph, with original punctuation kept as text. */
[data-reader-ornate-dropcap] [data-reader-initial-group],
[data-reader-ornate-dropcap] [data-reader-initial-prefix],
[data-reader-ornate-dropcap] [data-reader-initial-glyph] {
  display: inline;
  font: inherit;
  color: inherit;
  letter-spacing: inherit;
}
[data-reader-ornate-dropcap="auto"] [data-reader-initial-layout="float"]
.reader-paragraph[data-reader-initial-paragraph]:not([data-split-from]):not([data-reader-continuation]) {
  display: flow-root;
  text-indent: 0;
}
[data-reader-ornate-dropcap="auto"] [data-reader-initial-layout="float"]
.reader-paragraph[data-reader-initial-paragraph]:not([data-split-from]):not([data-reader-continuation]) > [data-reader-initial-group] {
  float: left;
  display: inline-flex;
  align-items: flex-start;
  height: calc(var(--reader-initial-line) * 2 - .25px);
  margin: 0 var(--reader-dropcap-gap, .16em) 0 0;
  padding: 0;
  text-indent: 0;
  vertical-align: baseline;
}
[data-reader-ornate-dropcap="auto"] [data-reader-initial-layout="float"]
.reader-paragraph[data-reader-initial-paragraph]:not([data-split-from]):not([data-reader-continuation]) > [data-reader-initial-group] > [data-reader-initial-prefix] {
  display: block;
  font-size: var(--reader-initial-body-size);
  line-height: var(--reader-initial-line);
}
[data-reader-ornate-dropcap="auto"] [data-reader-initial-layout="float"]
.reader-paragraph[data-reader-initial-paragraph]:not([data-split-from]):not([data-reader-continuation]) > [data-reader-initial-group] > [data-reader-initial-glyph] {
  display: block;
  font-size: var(--reader-initial-size);
  line-height: var(--reader-initial-size);
  letter-spacing: 0;
  color: var(--reader-dropcap-color, var(--reader-accent, currentColor));
  transform: translateY(var(--reader-initial-shift));
}

/* JS 只动画装饰，不改变正文区域尺寸。 */
.bookcraft--night .bc-script-star { transform-box: fill-box; transform-origin: center; }

