// 创作示例：用标准 Web Animations API 驱动页脚星标。
// 修改 turnDuration 可以调速；CSS 标题动效与正文排版独立保留。
(function () {
  var turnDuration = 18000;
  var currentPage = null, animation = null;

  function cancelAnimation() {
    if (animation) animation.cancel();
    animation = null;
  }
  function updateMotion(event) {
    // 翻页或重新分页后，释放旧页面的任务，不持有已经离开的 DOM。
    if (event.page !== currentPage) {
      cancelAnimation();
      currentPage = event.page;
    }
    // 静态截图和减少动态效果都使用 CSS 中的完整静态图案。
    if (!currentPage || event.state === 'settled' || event.reducedMotion) {
      cancelAnimation();
      return;
    }
    if (event.state === 'paused') {
      if (animation) animation.pause();
      return;
    }
    var star = currentPage.querySelector('[data-reader-script-star]');
    if (!star || typeof star.animate !== 'function') return;
    if (animation) animation.play();
    else animation = star.animate([
      {transform: 'rotate(0deg)'}, {transform: 'rotate(360deg)'}
    ], {duration: turnDuration + event.pageIndex % 4 * 1200, iterations: Infinity, easing: 'linear'});
    // 不返回 animation.finished，也不把无限动画传给 waitUntil。
  }
  var unsubscribe = readerTemplate.on('motionChange', updateMotion);
  readerTemplate.on('dispose', function () {
    unsubscribe();
    cancelAnimation();
    currentPage = null;
  });
}());

// 以下为分页前的标题适配、字体等待及首字排版，可按需修改。
(function () {
  var fontRequests = Object.create(null);
  function prepareFont(node, sample) {
    if (!document.fonts || !node) return Promise.resolve();
    var style = getComputedStyle(node);
    var key = style.fontFamily + '/' + style.fontStyle + '/' + style.fontWeight;
    if (fontRequests[key]) return fontRequests[key];
    fontRequests[key] = new Promise(function (resolve) {
      var finished = false;
      var timer = setTimeout(done, 2800);
      function done() {
        if (finished) return;
        finished = true; clearTimeout(timer); resolve();
      }
      Promise.resolve().then(function () {
        if (document.fonts.load && style.font) return document.fonts.load(style.font, sample);
      }).then(function () { return document.fonts.ready; }).then(done, done);
    });
    return fontRequests[key];
  }
  function number(value, fallback) {
    var parsed = parseFloat(value);
    return Number.isFinite(parsed) ? parsed : fallback;
  }
  function fitPage(event) {
    var shell = event.page.querySelector('.bookcraft');
    if (!shell) return;
    var flow = shell.querySelector('[data-reader-flow]');
    if (!flow) return;
    var flowStyle = getComputedStyle(flow);
    var fontSize = number(flowStyle.fontSize, 18);
    var lineHeight = number(flowStyle.lineHeight, fontSize * 1.6);
    var availableHeight = shell.getBoundingClientRect().height;
    var minimumBody = Math.max(lineHeight + 2, Math.min(lineHeight * 3 + 2, availableHeight * .44));
    var densities = ['', 'compact', 'minimal'];
    var title = shell.querySelector('.bc-title');
    shell.removeAttribute('data-bookcraft-density');
    shell.style.removeProperty('--bc-title-size');
    function fits() {
      var box = flow.getBoundingClientRect();
      return box.height + .25 >= minimumBody && box.width >= Math.min(fontSize * 3, 72);
    }
    for (var index = 0; index < densities.length; index++) {
      if (densities[index]) shell.setAttribute('data-bookcraft-density', densities[index]);
      if (fits()) return;
    }
    if (title) {
      var upper = number(getComputedStyle(title).fontSize, 24);
      var lower = Math.max(14, Math.min(18, fontSize));
      shell.style.setProperty('--bc-title-size', lower + 'px');
      // On a short viewport at the largest reader font, a complete title plus
      // one intact body line is still a useful page; the preferred three-line
      // reserve must not reject that valid composition.
      if (!fits()) minimumBody = lineHeight + 2;
      if (fits()) {
        for (var step = 0; step < 6 && upper - lower > .4; step++) {
          var middle = (lower + upper) / 2;
          shell.style.setProperty('--bc-title-size', middle.toFixed(2) + 'px');
          if (fits()) lower = middle; else upper = middle;
        }
        shell.style.setProperty('--bc-title-size', lower.toFixed(2) + 'px');
        return;
      }
    }
    // Prefer a complete fallback chapter over a clipped title or an empty first page.
    throw new Error('当前章名与字号无法在书页中完整排下，请使用基础排版或调整字号');
  }
  readerTemplate.on('beforePage', async function (event) {
    var shell = event.page.querySelector('.bookcraft');
    if (!shell) return;
    var title = shell.querySelector('.bc-title');
    var fontNode = title || shell.querySelector('[data-reader-flow]');
    await Promise.all([
      prepareFont(fontNode, title ? title.textContent.slice(0, 96) : '正文Aa'),
      prepareFont(shell.querySelector('[data-reader-flow]'), '正文汉字Aa')
    ]);
    event.page.__readerBookcraftFontsChecked = true;
    fitPage(event);
  });
}());
(function () {
  readerTemplate.on('beforePage', function (event) {
    var shell = event.page.querySelector('.bookcraft--night');
    if (!shell) return;
    shell.style.setProperty('--bc-night-delay', String(-(event.pageIndex % 8) * 1.7) + 's');
  });
}());

(function () {
  'use strict';
  var api = readerTemplate;
  var state = null, candidate = null, cache = new Map(), fontWaits = new Map(), pendingTimers = new Set();
  var canvas = document.createElement('canvas'), context = canvas.getContext('2d');
  var segmenter = typeof Intl !== 'undefined' && Intl.Segmenter ? new Intl.Segmenter('zh', {granularity: 'grapheme'}) : null;
  var ignored = 'script,style,noscript,[data-reader-text-ignore],[data-legado-image-action]';
  var prefixCharacters = '\u201c\u2018\u300c\u300e\uff08\u300a\u3008\u3010\u3014\u3016\u3018\u301a"\'';
  var active = true, eligibilityReason = 'not-prepared';

  function textOf(root) {
    var parts = [], walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT), node;
    while ((node = walker.nextNode())) {
      if (!node.parentElement.closest(ignored)) parts.push(node.data);
    }
    return parts.join('');
  }
  function han(code) {
    return code >= 0x3400 && code <= 0x4dbf || code >= 0x4e00 && code <= 0x9fff ||
      code >= 0xf900 && code <= 0xfaff || code >= 0x20000 && code <= 0x323af;
  }
  function initialParts(value) {
    var at = 0, prefixCount = 0;
    while (at < value.length && prefixCharacters.indexOf(value.charAt(at)) >= 0 && prefixCount < 4) {
      at++; prefixCount++;
    }
    if (!han(value.codePointAt(at))) return null;
    var rest = value.slice(at), glyph;
    if (segmenter) glyph = segmenter.segment(rest)[Symbol.iterator]().next().value.segment;
    else {
      var end = rest.codePointAt(0) > 0xffff ? 2 : 1;
      while (end < rest.length) {
        var code = rest.codePointAt(end);
        if (code >= 0xfe00 && code <= 0xfe0f || code >= 0xe0100 && code <= 0xe01ef) end += code > 0xffff ? 2 : 1;
        else break;
      }
      var next = rest.codePointAt(end);
      if (next === 0x200d || next >= 0x300 && next <= 0x36f) return null;
      glyph = rest.slice(0, end);
    }
    return {prefix: value.slice(0, at), glyph: glyph, length: at + glyph.length};
  }
  function restore() {
    if (!state) return;
    var group = state.group, parent = group.parentNode;
    if (parent) {
      while (group.firstChild) {
        var part = group.firstChild;
        if (part.nodeType === Node.ELEMENT_NODE &&
            (part.hasAttribute('data-reader-initial-prefix') || part.hasAttribute('data-reader-initial-glyph'))) {
          while (part.firstChild) parent.insertBefore(part.firstChild, group);
          group.removeChild(part);
        } else parent.insertBefore(part, group);
      }
      parent.removeChild(group);
      parent.normalize();
    }
    state.paragraph.removeAttribute('data-reader-initial-paragraph');
    state = null;
  }
  function firstParagraph() {
    var paragraphs = api.source.querySelectorAll('.reader-paragraph');
    for (var index = 0; index < paragraphs.length; index++) {
      if (/\S/.test(textOf(paragraphs[index]))) return paragraphs[index];
    }
    return null;
  }
  function firstText(paragraph) {
    var walker = document.createTreeWalker(paragraph, NodeFilter.SHOW_ELEMENT | NodeFilter.SHOW_TEXT), node;
    while ((node = walker.nextNode())) {
      if (node.nodeType === Node.ELEMENT_NODE) {
        if (/^(img|svg|video|canvas|br)$/.test(String(node.localName).toLowerCase())) return null;
      } else if (/\S/.test(node.data) && !node.parentElement.closest(ignored)) return node;
    }
    return null;
  }
  function prepare() {
    cache.clear();
    var paragraph = firstParagraph();
    if (state && state.paragraph === paragraph && state.group.parentNode === paragraph &&
        state.signature === textOf(paragraph)) {
      candidate = state;
      eligibilityReason = 'eligible';
      return;
    }
    restore();
    candidate = null;
    eligibilityReason = 'no-paragraph';
    paragraph = firstParagraph();
    if (!paragraph || paragraph.hasAttribute('data-reader-continuation')) return;
    var node = firstText(paragraph);
    // Leave existing clickable/ruby/styled inline structures exactly as authored.
    if (!node) { eligibilityReason = 'media-first'; return; }
    if (node.parentNode !== paragraph) { eligibilityReason = 'nested-inline'; return; }
    var parts = initialParts(node.data);
    if (!parts) { eligibilityReason = 'non-han-start'; return; }
    var signature = textOf(paragraph);
    var following = node.splitText(parts.length), glyph = node;
    var group = document.createElement('span'), prefix = null;
    group.setAttribute('data-reader-initial-group', 'bookcraft');
    paragraph.insertBefore(group, node);
    if (parts.prefix) {
      glyph = node.splitText(parts.prefix.length);
      prefix = document.createElement('span');
      prefix.setAttribute('data-reader-initial-prefix', '');
      prefix.appendChild(node);
      group.appendChild(prefix);
    }
    var letter = document.createElement('span');
    letter.setAttribute('data-reader-initial-glyph', '');
    letter.appendChild(glyph);
    group.appendChild(letter);
    paragraph.setAttribute('data-reader-initial-paragraph', '');
    state = candidate = {paragraph: paragraph, group: group, prefix: prefix, letter: letter,
      glyph: parts.glyph, prefixText: parts.prefix, rest: signature.slice(parts.length), signature: signature};
    eligibilityReason = 'eligible';
    if (textOf(paragraph) !== signature || following.parentNode !== paragraph) {
      restore(); candidate = null;
    }
  }
  function number(style, name) { return parseFloat(style.getPropertyValue(name)) || 0; }
  function font(style, size) {
    return style.fontStyle + ' ' + style.fontWeight + ' ' + size + 'px ' + style.fontFamily;
  }
  function ink(value, fontValue) {
    if (!context) return null;
    context.font = fontValue;
    var metrics = context.measureText(value);
    if (!Number.isFinite(metrics.actualBoundingBoxAscent) || !Number.isFinite(metrics.actualBoundingBoxDescent)) return null;
    return {ascent: metrics.actualBoundingBoxAscent, descent: metrics.actualBoundingBoxDescent, width: metrics.width};
  }
  function baseline(page, style, size, line) {
    // Synthetic calibration text is constant, never a duplicate of book content.
    var probe = document.createElement('div'), marker = document.createElement('i');
    probe.setAttribute('aria-hidden', 'true');
    probe.setAttribute('data-reader-decoration', '');
    probe.style.cssText = 'position:absolute;left:-100000px;top:0;margin:0;padding:0;border:0;white-space:nowrap;visibility:hidden;pointer-events:none;';
    probe.style.font = font(style, size);
    probe.style.lineHeight = line + 'px';
    probe.textContent = '\u7530';
    marker.style.cssText = 'display:inline-block;width:0;height:0;margin:0;padding:0;border:0;vertical-align:baseline;';
    probe.appendChild(marker);
    page.appendChild(probe);
    var value = marker.getBoundingClientRect().top - probe.getBoundingClientRect().top;
    probe.remove();
    return value;
  }
  function calibration(page, style, size, line) {
    var key = font(style, size) + '|' + line + '|' + candidate.glyph;
    if (cache.has(key)) return cache.get(key);
    var bodyInk = ink('\u7530', font(style, size)), unitInk = ink(candidate.glyph, font(style, 100));
    var result;
    if (bodyInk && unitInk && bodyInk.ascent + bodyInk.descent > 0 && unitInk.ascent + unitInk.descent > 0) {
      var target = line + bodyInk.ascent + bodyInk.descent;
      var capSize = target * 100 / (unitInk.ascent + unitInk.descent);
      var capInk = ink(candidate.glyph, font(style, capSize));
      var start = baseline(page, style, size, line) - bodyInk.ascent;
      var shift = start - (baseline(page, style, capSize, capSize) - capInk.ascent);
      result = {size: capSize, shift: shift, mode: 'ink-measured', top: start, bottom: start + target};
    } else {
      // Older Canvas implementations still get a two-line em grid with no px cap.
      result = {size: line + size, shift: (line - size) / 2, mode: 'em-grid', top: 0, bottom: line * 2};
    }
    if (!Number.isFinite(result.size) || result.size <= 0 || result.size > line * 4 ||
        !Number.isFinite(result.shift) || result.top < -.5 || result.bottom > line * 2 + .5) result = null;
    cache.set(key, result);
    return result;
  }
  function fontsReady(page, style, size) {
    if (page.__readerBookcraftFontsChecked || !document.fonts || !document.fonts.load) return Promise.resolve();
    var fontValue = font(style, size), key = fontValue + '|' + candidate.glyph;
    if (fontWaits.has(key)) return fontWaits.get(key);
    var work = (async function () {
      var timer;
      try {
        await Promise.race([
          Promise.resolve().then(function () { return document.fonts.load(fontValue, '\u7530' + candidate.glyph); }).catch(function () {}),
          new Promise(function (resolve) { timer = setTimeout(resolve, 3000); pendingTimers.add(timer); })
        ]);
